{%- set doc -%}{% raw %}query products($first: Int!, $after: String, $query: String) {
  products(first: $first, after: $after, query: $query, sortKey: UPDATED_AT) {
    nodes { id title handle status vendor updatedAt totalInventory variants(first: 20) { nodes { id sku price } } }
    pageInfo { hasNextPage endCursor }
  }
}{% endraw %}{%- endset -%}{{ {"query": (params.get('query') or doc), "variables": (params.get('variables') | from_json({}))} | tojson }}

{%- set doc -%}{% raw %}query product($id: ID!) {
  product(id: $id) {
    id title handle status vendor productType tags descriptionHtml updatedAt
    options { name values }
    variants(first: 100) { nodes { id title sku barcode price compareAtPrice inventoryQuantity inventoryItem { id tracked } } }
    media(first: 10) { nodes { id mediaContentType alt ... on MediaImage { image { url } } } }
  }
}{% endraw %}{%- endset -%}{{ {"query": (params.get('query') or doc), "variables": (params.get('variables') | from_json({}))} | tojson }}

