{%- set doc -%}{% raw %}query order($id: ID!) {
  order(id: $id) {
    id name email phone createdAt updatedAt processedAt cancelledAt cancelReason closed test tags note
    displayFinancialStatus displayFulfillmentStatus
    currentSubtotalPriceSet { shopMoney { amount currencyCode } }
    currentTotalTaxSet { shopMoney { amount currencyCode } }
    currentTotalPriceSet { shopMoney { amount currencyCode } presentmentMoney { amount currencyCode } }
    customer { id email firstName lastName }
    shippingAddress { name address1 address2 city provinceCode zip countryCodeV2 phone }
    billingAddress { name address1 city provinceCode zip countryCodeV2 }
    lineItems(first: 100) {
      nodes { id sku title quantity currentQuantity unfulfilledQuantity variant { id } originalUnitPriceSet { shopMoney { amount currencyCode } } }
    }
    fulfillmentOrders(first: 20) {
      nodes { id status requestStatus assignedLocation { name location { id } } lineItems(first: 100) { nodes { id remainingQuantity lineItem { id sku } } } }
    }
    fulfillments(first: 20) { id status trackingInfo { company number url } }
  }
}{% endraw %}{%- endset -%}{{ {"query": (params.get('query') or doc), "variables": (params.get('variables') | from_json({}))} | tojson }}

